import{_ as e,o as s,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"56. Linking Multiple Files","description":"The Little Book of C — 56. Linking Multiple Files","frontmatter":{"title":"56. Linking Multiple Files","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Compilation and Build"],"description":"The Little Book of C — 56. Linking Multiple Files","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":56,"sidebarWeight":56,"lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/056-Linking Multiple Files","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/056-Linking Multiple Files"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/056-Linking Multiple Files.md","filePath":"posts/c教程/en-US/06-Compilation and Build/056-Linking Multiple Files.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/06-Compilation and Build/056-Linking Multiple Files.md"};function p(l,a,o,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/056-Linking Multiple Files)</p><p>When a program grows beyond one<code>.c</code> file, the compiler must combine them into a single executable. This process, linking, is what joins all your functions, variables, and library references into one binary.</p><p>You’ve already seen snippets of it with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o -o app</span></span></code></pre></div><p>But now we’ll go deeper into how linking works and what happens when things go wrong.</p><h4 id="step-1-the-two-compilation-phases" tabindex="-1">Step 1. The Two Compilation Phases <a class="header-anchor" href="#step-1-the-two-compilation-phases" aria-label="Permalink to &quot;Step 1. The Two Compilation Phases&quot;">​</a></h4><p>Every C build has two main phases:</p><p>Compilation – each<code>.c</code> file becomes a<code>.o</code>(object file).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c -o main.o</span></span>
<span class="line"><span>gcc -c math.c -o math.o</span></span></code></pre></div><p>Each<code>.o</code> file contains machine code and symbol tables (lists of what it defines and what it needs).</p><p>Linking – the linker (<code>ld</code>) merges all<code>.o</code> files and libraries into an executable:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o -o app</span></span></code></pre></div><p>If any symbol is missing (like an undefined function), the linker fails.</p><h4 id="step-2-what-are-symbols" tabindex="-1">Step 2. What Are Symbols? <a class="header-anchor" href="#step-2-what-are-symbols" aria-label="Permalink to &quot;Step 2. What Are Symbols?&quot;">​</a></h4><p>Symbols are names the compiler uses to track functions and global variables. There are two kinds:</p><ul><li>Defined symbols – functions or variables provided by this file.</li><li>Undefined symbols – things it needs from another file.</li></ul><p>Example:</p><p>math.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span></code></pre></div><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int, int);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and link:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c math.c</span></span>
<span class="line"><span>gcc main.o math.o -o app</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5</span></span></code></pre></div><p>If you forget to link<code>math.o</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -o app</span></span></code></pre></div><p>You’ll get:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>undefined reference to \`add&#39;</span></span></code></pre></div><h4 id="step-3-using-header-files-for-declarations" tabindex="-1">Step 3. Using Header Files for Declarations <a class="header-anchor" href="#step-3-using-header-files-for-declarations" aria-label="Permalink to &quot;Step 3. Using Header Files for Declarations&quot;">​</a></h4><p>Each<code>.c</code> file should declare (not define) external functions in a header:</p><p>math.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_H</span></span>
<span class="line"><span>#define MATH_H</span></span>
<span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>Then include it in both<code>main.c</code> and<code>math.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;math.h&quot;</span></span></code></pre></div><p>This ensures consistency between the declaration and definition.</p><h4 id="step-4-linking-object-files-and-libraries" tabindex="-1">Step 4. Linking Object Files and Libraries <a class="header-anchor" href="#step-4-linking-object-files-and-libraries" aria-label="Permalink to &quot;Step 4. Linking Object Files and Libraries&quot;">​</a></h4><p>You can link any number of<code>.o</code> files:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o util.o io.o -o app</span></span></code></pre></div><p>You can also link with libraries:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -lm -o app</span></span></code></pre></div><p>(<code>-lm</code> links the math library that provides functions like<code>sqrt</code>,<code>sin</code>, etc.)</p><p>The<code>-l</code> flag searches<code>/usr/lib</code> and<code>/lib</code> by default.</p><p>Custom library example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmyutils -o app</span></span></code></pre></div><p>Here,<code>-L.</code> adds the current directory to the library search path, and<code>-lmyutils</code> links<code>libmyutils.a</code> or<code>libmyutils.so</code>.</p><h4 id="step-5-the-order-of-linking-matters" tabindex="-1">Step 5. The Order of Linking Matters <a class="header-anchor" href="#step-5-the-order-of-linking-matters" aria-label="Permalink to &quot;Step 5. The Order of Linking Matters&quot;">​</a></h4><p>The linker reads from left to right. If a symbol is used before its definition appears, it might fail.</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -lm main.o -o app    # ❌ wrong order</span></span>
<span class="line"><span>gcc main.o -lm -o app    # ✅ correct</span></span></code></pre></div><p>Always list libraries after the object files that need them.</p><h4 id="step-6-splitting-and-linking-a-multi-file-project" tabindex="-1">Step 6. Splitting and Linking a Multi-File Project <a class="header-anchor" href="#step-6-splitting-and-linking-a-multi-file-project" aria-label="Permalink to &quot;Step 6. Splitting and Linking a Multi-File Project&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>├── main.c</span></span>
<span class="line"><span>├── math.c</span></span>
<span class="line"><span>├── io.c</span></span>
<span class="line"><span>├── math.h</span></span>
<span class="line"><span>├── io.h</span></span>
<span class="line"><span>└── Makefile</span></span></code></pre></div><p>Makefile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>OBJ = main.o math.o io.o</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(OBJ) -o $(TARGET)</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p>Now, just run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>The Makefile takes care of compiling and linking everything in order.</p><h4 id="tiny-code-building-a-small-modular-program" tabindex="-1">Tiny Code: Building a Small Modular Program <a class="header-anchor" href="#tiny-code-building-a-small-modular-program" aria-label="Permalink to &quot;Tiny Code: Building a Small Modular Program&quot;">​</a></h4><p>math.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int square(int x) { return x * x; }</span></span>
<span class="line"><span>int cube(int x) { return x * x * x; }</span></span></code></pre></div><p>math.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_H</span></span>
<span class="line"><span>#define MATH_H</span></span>
<span class="line"><span>int square(int x);</span></span>
<span class="line"><span>int cube(int x);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;square(3) = %d\\n&quot;, square(3));</span></span>
<span class="line"><span>    printf(&quot;cube(2) = %d\\n&quot;, cube(2));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Build manually:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c math.c -o math.o</span></span>
<span class="line"><span>gcc -c main.c -o main.o</span></span>
<span class="line"><span>gcc main.o math.o -o app</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>square(3) = 9</span></span>
<span class="line"><span>cube(2) = 8</span></span></code></pre></div><h4 id="step-7-static-vs-dynamic-linking" tabindex="-1">Step 7. Static vs Dynamic Linking <a class="header-anchor" href="#step-7-static-vs-dynamic-linking" aria-label="Permalink to &quot;Step 7. Static vs Dynamic Linking&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>File</th><th>Description</th></tr></thead><tbody><tr><td>Static</td><td><code>.a</code></td><td>Code is copied into the executable</td></tr><tr><td>Dynamic</td><td><code>.so</code></td><td>Code is shared at runtime via system libraries</td></tr></tbody></table><p>Static linking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmath -static -o app</span></span></code></pre></div><p>Dynamic linking (default):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmath -o app</span></span></code></pre></div><p>Dynamic executables are smaller and share libraries across programs.</p><h4 id="step-8-inspecting-linked-binaries" tabindex="-1">Step 8. Inspecting Linked Binaries <a class="header-anchor" href="#step-8-inspecting-linked-binaries" aria-label="Permalink to &quot;Step 8. Inspecting Linked Binaries&quot;">​</a></h4><p>To see which symbols are defined or missing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm main.o | head</span></span></code></pre></div><p>Or for a full binary:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -t app | less</span></span>
<span class="line"><span>ldd app</span></span></code></pre></div><p><code>ldd</code> shows which shared libraries the program depends on.</p><h4 id="step-9-common-linking-errors" tabindex="-1">Step 9. Common Linking Errors <a class="header-anchor" href="#step-9-common-linking-errors" aria-label="Permalink to &quot;Step 9. Common Linking Errors&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Error</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>undefined reference to </code></td><td>Missing<code>.o</code> or library</td><td>Add all object files or correct<code>-l</code> flags</td></tr><tr><td><code>multiple definition of </code></td><td>Same function defined in multiple files</td><td>Use<code>extern</code> in declarations</td></tr><tr><td><code>cannot find -lfoo</code></td><td>Missing library file</td><td>Check<code>-L</code> paths or install dev package</td></tr><tr><td><code>relocation truncated</code></td><td>Mismatched architectures</td><td>Ensure all files are built for same target</td></tr></tbody></table><h4 id="step-10-inline-vs-external-linking" tabindex="-1">Step 10. Inline vs External Linking <a class="header-anchor" href="#step-10-inline-vs-external-linking" aria-label="Permalink to &quot;Step 10. Inline vs External Linking&quot;">​</a></h4><p>Inline functions defined as<code>static inline</code> in headers do not require linking, each<code>.c</code> file gets its own copy. But normal functions in<code>.c</code> files must be linked exactly once.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Linking is where your program becomes whole. It teaches you:</p><ul><li>How<code>.o</code> and<code>.h</code> files interact</li><li>How libraries integrate with your binaries</li><li>How to debug missing symbols and multiple definitions</li><li>How modular design affects build architecture</li></ul><p>Understanding the linker is essential for building scalable, multi-file systems, from small utilities to entire kernels.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Create a program with 3<code>.c</code> files and 3<code>.h</code> files.</li><li>Intentionally omit one object file and observe the linker error.</li><li>Use<code>nm</code> to inspect which functions each<code>.o</code> defines and references.</li><li>Build a static library (<code>ar rcs libutils.a util.o</code>) and link it manually.</li><li>Use<code>ldd</code> to list shared libraries your compiled program depends on.</li></ol><p>Next, you’ll learn how to create and use static and shared libraries, the modular building blocks that every serious C project relies on for reusability and scalability.</p>`,93)])])}const g=e(t,[["render",p]]);export{u as __pageData,g as default};
